import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

// The committed demo sample (examples/output-trace, regenerated by examples/regen-output-trace.mjs from `npm run demo`'s
// path). CI's demo job asserts the same on the live run via examples/assert-trace-chain.mjs.
const dir = join(__dirname, "..", "examples", "output-trace");
const w = JSON.parse(readFileSync(join(dir, "walkthrough.json"), "utf8"));
const html = readFileSync(join(dir, "index.html"), "utf8");
const f = w.findings.find((x: { severity: string }) => x.severity === "high");
const mqItem = () => f.ruled_out.find((r: { claim: string }) => /排除 MQ 问题/.test(r.claim));
const ev = (id: string) => w.evidence.find((e: { id: string }) => e.id === id);

describe("demo: RocketMQ backlog is checked through the real mqadmin preset and ruled out", () => {
  it("ruled-out item is backed by core mqadmin consumerProgress evidence whose sha256 matches the file", () => {
    const r = mqItem();
    expect(r.claim).toMatch(/^查过消息堆积，消费正常，排除 MQ 问题/);
    const e = ev(r.evidence_ids[0]);
    expect(e).toMatchObject({ kind: "cli_output", executedBy: "core" });
    expect(e.source).toMatch(/^run_cli:mqadmin consumerProgress -g order-pricing-consumer -t ORDER_CREATED -n 127\.0\.0\.1:\d+$/);
    const text = readFileSync(join(dir, e.path), "utf8");
    expect(text).toMatch(/^Consume Diff Total: 0$/m);
    expect(text).toMatch(/^#Topic +#Broker Name +#QID +#Broker Offset +#Consumer Offset +#Diff +#Inflight +#LastTime$/m);
    expect(createHash("sha256").update(readFileSync(join(dir, e.path))).digest("hex")).toBe(e.sha256);
    expect(w.checkResults.find((x: { checkId: string }) => x.checkId === r.check_id).status).toBe("pass");
    const log = readFileSync(join(dir, "commands.jsonl"), "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l)).find((l) => l.evidenceId === e.id);
    expect(log).toMatchObject({ connector: "mqadmin", outputSha256: e.sha256, cli: { name: "mqadmin", version: "mqadmin 5.5.1-mock", profile: "demo-readonly" } });
  });

  it("the report page shows the exclusion with the full sha256", () => {
    const e = ev(mqItem().evidence_ids[0]);
    expect(html).toContain('<div class="ruled-out" data-ruled-out="2"><b>已排除</b>');
    expect(html).toContain(`data-evidence="${e.id}"`);
    expect(html).toContain(`<code class="sha256" data-sha256="${e.sha256}">${e.sha256}</code>`);
  });

  it("the root-cause chain is unchanged: HTTP 500 → metric → Langfuse → MongoDB → pricing.js, no mqadmin step", () => {
    const kinds = f.root_cause_chain.map((l: { evidence_ids: string[] }) => l.evidence_ids.map((i) => {
      const e = ev(i); return e.mcpCall ? `${e.kind}:${e.mcpCall.connector}` : e.kind;
    }).join("+"));
    expect(kinds).toEqual(["har+http", "metric", "mcp_result:langfuse", "mcp_result:mongodb", "log"]);
    expect(f.root_cause_chain.at(-1).claim).toMatch(/pricing\.js:3/);
    const mq = mqItem().evidence_ids[0];
    expect(f.evidenceIds).not.toContain(mq);
    expect(JSON.stringify(f.root_cause_chain)).not.toMatch(/mqadmin|MQ|aliyun|SLS/);
    expect(f.root_cause_chain).toHaveLength(5);
  });
});

describe("recordFinding ruled_out", () => {
  it("is stored outside the chain and must cite existing evidence", async () => {
    const { mockCore } = await import("./helpers.js");
    const { core, root } = mockCore({});
    const id = (await core.startWalkthrough({ title: "ro", sandbox: { cwd: root, up: "true", down: "true" } })).id;
    await core.planChecks(id, { goal: "g", checks: [{ id: "c1", intent: "i", method: "http", target: "GET http://x/", expect: { type: "status", value: 200 }, severity_if_fail: "high" }] });
    const a = await core.captureEvidence(id, { type: "submit", checkId: "c1", kind: "http", source: { tool: "t" }, content: "HTTP/1.1 500" });
    const b = await core.captureEvidence(id, { type: "submit", checkId: "c1", kind: "http", source: { tool: "t" }, content: "backlog 0" });
    const chain = [{ claim: "500", kind: "observed" as const, evidence_ids: [a.id] }];
    await expect(core.recordFinding(id, { title: "t", severity: "high", symptom: "s", root_cause_chain: chain, ruled_out: [{ claim: "x", evidence_ids: ["ev-99"] }] })).rejects.toThrow();
    await expect(core.recordFinding(id, { title: "t", severity: "high", symptom: "s", root_cause_chain: chain, ruled_out: [{ claim: "x", evidence_ids: [] }] })).rejects.toThrow(/needs evidence/);
    const f = await core.recordFinding(id, { title: "t", severity: "high", symptom: "s", root_cause_chain: chain, ruled_out: [{ claim: "排除 X", evidence_ids: [b.id] }] });
    expect(f.ruled_out).toEqual([{ claim: "排除 X", evidence_ids: [b.id] }]);
    expect(f.evidenceIds).toEqual([a.id]);
  });
});
